function largestMagicSquare(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const rowSum = Array.from({ length: m }, () => new Array(n + 1).fill(0));
  const colSum = Array.from({ length: m + 1 }, () => new Array(n).fill(0));
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
      colSum[i + 1][j] = colSum[i][j] + grid[i][j];
    }
  }

  for (let k = Math.min(m, n); k >= 2; k--) {
    for (let top = 0; top + k <= m; top++) {
      for (let left = 0; left + k <= n; left++) {
        const target = rowSum[top][left + k] - rowSum[top][left];
        let magic = true;
        for (let d = 1; d < k && magic; d++) {
          magic = rowSum[top + d][left + k] - rowSum[top + d][left] === target;
        }
        for (let d = 0; d < k && magic; d++) {
          magic = colSum[top + k][left + d] - colSum[top][left + d] === target;
        }
        let down = 0;
        let up = 0;
        for (let d = 0; d < k && magic; d++) {
          down += grid[top + d][left + d];
          up += grid[top + d][left + k - 1 - d];
        }
        if (magic && down === target && up === target) {
          return k;
        }
      }
    }
  }
  return 1;
}

